package com.academy.lms.course;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="course_sections") public class CourseSection { @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="course_id")private Course course;@Column(nullable=false)private String title;@Column(nullable=false)private int position;@Column(name="created_at")private Instant createdAt;@OneToMany(mappedBy="section",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("position")private List<Lesson> lessons=new ArrayList<>();protected CourseSection(){}public CourseSection(Course c,String t,int p){id=UUID.randomUUID();course=c;title=t;position=p;createdAt=Instant.now();}public UUID getId(){return id;}public String getTitle(){return title;}public int getPosition(){return position;}public List<Lesson> getLessons(){return List.copyOf(lessons);}public Course getCourse(){return course;}public void addLesson(Lesson l){lessons.add(l);}}

